/**
 * Regression guard for the webview HTML/script generated by
 * KubesealPanelProvider._getHtml().
 *
 * The entire panel UI (HTML, CSS, and client-side JS) is built as one giant
 * TypeScript template literal in src/ui/panelProvider.ts. Because of that,
 * an unescaped `\n`, `\s`, `\d`, etc. written inside a *nested* JS string
 * literal (e.g. `'a\nb'` meant to end up in the browser) is interpreted by
 * TypeScript itself while building the outer string — silently splicing a
 * real newline/character into the emitted script instead of a literal
 * backslash-escape. That breaks the inline <script> with a syntax error
 * that VS Code's webview never surfaces anywhere the extension host can
 * see, so the whole panel goes dead: no button, tab, or listener responds.
 * (Fixed sequences must be written as `\\n`, `\\s`, etc. in the TS source.)
 *
 * This exact bug shipped once. This test compiles the real generated
 * <script> block with Node's `vm` module (parse-only, equivalent to
 * `node --check`) so any future escaping mistake fails here instead of
 * shipping silently.
 *
 * Requires `npm run compile` to have been run first (uses out/ui/panelProvider.js).
 * Usage: node tests/panel-webview-test.mjs
 */

import vm from 'vm';
import Module from 'module';
import { createRequire } from 'module';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');

const C = { reset: '\x1b[0m', bold: '\x1b[1m', green: '\x1b[32m', red: '\x1b[31m', dim: '\x1b[2m' };
const pass = `${C.green}✔${C.reset}`;
const fail = `${C.red}✖${C.reset}`;

let totalPass = 0;
let totalFail = 0;

function assert(cond, label) {
    if (cond) {
        console.log(`  ${pass} ${label}`);
        totalPass++;
    } else {
        console.log(`  ${fail} ${label}`);
        totalFail++;
    }
}

function loadPanelHtml() {
    // Stub the `vscode` module so the compiled extension code can be
    // require()'d outside the VS Code runtime, standalone-test style.
    const origResolve = Module._resolveFilename;
    Module._resolveFilename = function (request, ...args) {
        if (request === 'vscode') {
            return join(__dirname, 'stubs', 'vscode-stub.js');
        }
        return origResolve.call(this, request, ...args);
    };

    const require = createRequire(import.meta.url);
    const compiledPath = join(ROOT, 'out', 'ui', 'panelProvider.js');
    const { KubesealPanelProvider } = require(compiledPath);

    Module._resolveFilename = origResolve;

    const provider = new KubesealPanelProvider('file:///stub-extension-uri');
    // _getHtml is private in TS but plain JS at runtime.
    return provider['_getHtml']();
}

async function main() {
    console.log(`\n${C.bold}═══════════════════════════════════════════════════`);
    console.log(`  kubeseal-vscode  ·  Panel Webview Script Test`);
    console.log(`═══════════════════════════════════════════════════${C.reset}`);

    let html;
    try {
        html = loadPanelHtml();
        assert(true, 'KubesealPanelProvider._getHtml() ran without throwing');
    } catch (e) {
        assert(false, `KubesealPanelProvider._getHtml() ran without throwing — ${e.message}`);
        console.log(
            `\n${C.red}FATAL: could not generate panel HTML, skipping remaining checks.${C.reset}\n` +
                `Did you run "npm run compile" first?\n`
        );
        process.exit(1);
    }

    assert(typeof html === 'string' && html.length > 0, '_getHtml() returns non-empty HTML');

    const scriptMatches = [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)];
    assert(scriptMatches.length >= 1, 'generated HTML contains at least one <script> block');

    const inlineScript = scriptMatches.length ? scriptMatches[scriptMatches.length - 1][1] : '';
    assert(
        inlineScript.includes('acquireVsCodeApi'),
        'located the main webview script block (contains acquireVsCodeApi)'
    );

    try {
        // Parse-only, mirrors `node --check` — never executes the script
        // (no real DOM/vscode API available here), just proves it's valid JS.
        new vm.Script(inlineScript, { filename: 'webview-inline-script.js' });
        assert(true, 'inline webview script parses without a syntax error');
    } catch (e) {
        assert(false, `inline webview script parses without a syntax error — ${e.message}`);
    }

    const styleMatches = [...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/g)];
    assert(styleMatches.length >= 1, 'generated HTML contains at least one <style> block');

    const total = totalPass + totalFail;
    console.log(`\n${C.bold}═══════════════════════════════════════════════════`);
    console.log(
        `  Results:  ${C.green}${totalPass} passed${C.reset}  ${
            totalFail > 0 ? C.red : C.dim
        }${totalFail} failed${C.reset}  ${C.dim}/ ${total} total${C.reset}`
    );
    console.log(`${C.bold}═══════════════════════════════════════════════════${C.reset}\n`);

    if (totalFail > 0) process.exit(1);
}

main();
